export function SvgShimmer({ className }: Readonly<{ className: string }>) {
  const uniqueId = React.useId();
  return (
    <svg
      className={className}
      version="1.1"
      xmlns="http://www.w3.org/2000/svg"
      xmlnsXlink="http://www.w3.org/1999/xlink"
    >
      <defs>
        <linearGradient id={`g-${uniqueId}`} x1="0%" y1="0%" x2="100%" y2="0%">
          <stop offset="0%" stopColor="#ececec" />
          <stop offset="100%" stopColor="#f7f7f7" />
        </linearGradient>
      </defs>

      <rect width="100%" height="100%" fill={`url(#g-${uniqueId})`}>
        <animate
          attributeName="fill"
          values="#ececec; #f7f7f7; #ececec"
          dur="1.5s"
          repeatCount="indefinite"
        />
      </rect>
    </svg>
  );
}

